{
  "version": "matched_cold_bank_v05",
  "block": 2,
  "arm": "relations",
  "candidates": [
    {
      "name": "neighbor_clique_ratio",
      "features": [
        {
          "name": "neighbor_clique_cost",
          "expression": {
            "op": "clique_cover_weight",
            "args": [
              {
                "op": "neighbors",
                "args": [{"op": "root", "args": []}]
              }
            ]
          }
        }
      ],
      "rule": "weight / max(1.0, 1.0 + neighbor_clique_cost)",
      "rationale": "Estimate blocked neighboring opportunity through a clique-partition upper bound and rank root weight relative to that cost."
    },
    {
      "name": "neighbor_packing_ratio",
