            "args": [
              {
                "op": "neighbors",
                "args": [{"op": "root", "args": []}]
              }
            ]
          }
        }
      ],
      "rule": "weight / max(1.0, 1.0 + neighbor_greedy_weight)",
      "rationale": "Use a feasible neighboring packing to estimate the alternatives excluded by choosing the root."
    },
    {
      "name": "clique_weight_share",
      "features": [
        {
          "name": "neighbor_clique_cost",
