        }
      ],
      "rule": "weight * (weight / max(1.0, 1.0 + weight + neighbor_clique_cost))",
      "rationale": "Discount absolute root value by its share of root weight and estimated neighboring competition."
    },
    {
      "name": "clique_degree_blend",
